package com.example.lab16; import android.os.Bundle; import android.view.*; import android.widget.*; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity { Spinner spinnerCourse; TextView txtResult; String[] courses={"Select Course","MCA","BCA","BSc Computer Science","MSc Computer Science"}; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);spinnerCourse=findViewById(R.id.spinnerCourse);txtResult=findViewById(R.id.txtResult);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,courses);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinnerCourse.setAdapter(adapter);spinnerCourse.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> parent,View view,int position,long id){String selected=courses[position];if(position!=0){txtResult.setText("Selected Course: "+selected);Toast.makeText(MainActivity.this,"You selected "+selected,Toast.LENGTH_SHORT).show();}}public void onNothingSelected(AdapterView<?> parent){txtResult.setText("Selected Course: None");}});}}